   "각 힘을 압력으로 바꾼다. 누를 때는 P = 1 + (m kg × 9.8) ÷ (A × 10.13), 당길 때는 P = 1 − F ÷ (A × 10.13) 로 계산해 1회·2회 칸에 적고(1 atm = 10.13 N/cm²), 평균을 낸 뒤 압력 × 부피를 계산해 마지막 칸을 채운다.",
