  "repeat": 2,
  "tips": "필요한 힘은 A = 5.7 cm² 일 때 20 mL 가 약 29 N(저울 약 2.9 kg), 55 mL 가 약 26 N 이므로 저울 범위를 미리 확인한다. 선생님이 모둠마다 5·7·9…19 mL 를 나누어 맡기면 30 mL 대신 5 mL 에서 막고 당기는 쪽만 잰다(19 mL 에서 약 43 N). 같은 부피에서 막은 모둠끼리는 P×V 로 결과를 합칠 수 있다.",
