  "why": "전기 전도도(μS/cm)는 전극 사이 용액의 저항을 잰 뒤 그 역수(전도)에 보정된 셀 상수를 곱해 얻는 값이다. 멀티미터의 저항 모드나 건전지·전류계로 클립 전극에 직류를 흘리면 전극이 분극되어 값이 계속 흔들리고, 흔들리지 않더라도 셀 상수를 모르니 μS/cm 로 환산할 수 없다. 전구가 켜지는지 보는 방법은 이온이 있다·없다만 가릴 뿐 '얼마나 많은지'는 못 잰다.",
