  "repeat": 2,
  "tips": "온도계는 광원 빛이 직접 닿지 않도록 잎 그늘 쪽에 눕히고, 눈금은 두 사람이 같은 시각에 읽어 확인하며 용기가 짧으면 잎을 한쪽으로 몰고 온도계를 대각선으로 눕힌다. 조도계 앱은 학급 전체가 같은 스마트폰 하나로 같은 위치에서 재어야 모둠 간 밝기 비교가 흐트러지지 않는다.",
  "limit": "종속 변인인 이산화 탄소 감소량이 자기 모둠 값이 아니라 예시 값이라 빛과 광합성량의 관계를 스스로 확인한 것이 아니며, 직접 잰 밝기·온도는 예시 표와 다른 용기의 값이라 같은 행에 넣을 수 없고 조도계 앱은 기기마다 lx 값이 달라 거칠다.",
  "safety": "LED 광원을 3개까지 켜면 뜨거워지므로 전구와 용기를 맨손으로 오래 만지지 않고 광원과 용기 사이 거리를 둔다.",
  "why": "종속 변인인 이산화 탄소 농도(ppm)를 재는 흔한 도구가 중학교 과학실에 없다. BTB 용액의 색 변화는 이산화 탄소가 줄었다는 것만 보여 주고 ppm 수치를 주지 않아 광원 개수별 감소량을 비교할 수 없다.",
  "alt": "예시 자료 표(처음·나중 이산화 탄소 농도·감소량·밝기·온도 6열)를 받아 감소량 계산·막대그래프·온도 통제 확인·해석만 직접 한다. 밝기(스마트폰 조도계 앱, 차선)와 온도(알코올 온도계)는 실제 용기를 꾸며 별도 확인표에 직접 재어 광원 개수가 늘면 밝기가 커지는지·10분 뒤 온도가 얼마나 오르는지 변인 통제 감각을 익히는 데만 쓰고 학습지 표의 예시 값과 섞지 않는다. 보조로 BTB 용액을 접시에 담아 함께 넣으면 색 변화로 이산화 탄소가 줄었음을 눈으로 확인할 수 있다."
