  "tips": "이쑤시개는 심지 바로 위, 어두운 불꽃심이 보이는 높이로 넣어야 세 자리를 모두 지난다. 심지에는 닿지 않게 하고 매번 새것을 쓰며, 넣는 시간은 초시계로 2초에 맞춘다. 손가락으로 문질러 묻어나는 검댕은 그을음이지 탄 자국이 아니므로, 문질러도 남는 갈색·검은 탄 자국만 보고 순위를 정한다. 예시 값을 옮겨 적을 때는 두 사람이 나란히 읽어 자릿수 실수를 막는다.",
