  "why": "촛불 온도는 700~1,000℃ 여서 알코올 온도계(최고 약 110℃)나 디지털 조리용 온도계(약 300℃)의 범위를 훌쩍 넘고, 넣으면 온도계가 깨지거나 고장 난다. 적외선 온도계는 투명한 불꽃 기체가 아니라 뒤쪽 물체의 표면 온도를 재므로 쓸 수 없다. 온도(TEMP) 기능이 있는 멀티미터도 딸려 오는 비드형 탐침은 대개 수백 ℃까지만 견디므로, 불꽃에 넣으면 피복이 타고 테플론 피복에서는 유독 기체가 나온다. 그래서 학교에 있는 도구로는 불꽃의 ℃ 값을 안전하게 얻을 수 없다.",
  "alt": "내열 장갑·보안경·실험복을 입고, 이쑤시개(또는 나무젓가락)를 핀셋으로 잡아 심지 바로 위 어두운 불꽃심이 보이는 높이에서 심지에 닿지 않게 불꽃을 가로질러 2초 넣었다 뺀다. 어느 자리가 가장 많이(진하게) 탔는지 보고, 새 이쑤시개로 모두 3번 되풀이해 세 자리의 순위를 ‘가장 많이 탐·중간·거의 안 탐’으로 활동지에 먼저 적는다. 손가락으로 문질러 묻어나는 검댕은 그을음이므로 탄 자국으로 치지 않고, 다 쓴 이쑤시개는 물에 담가 끈다. 그다음 [자료 받기 (예시 값)]으로 온도 값을 받아 표를 채우고, 막대그래프·범위·평균을 구해 탄 자국으로 정한 순위와 견준다."
