  "alt": "③ 재기에서 [자료 받기]를 눌러 예시 값을 표에 넣는다. 이 값은 잎 30 g 을 밀봉하고 빛을 막은 조건을 가정해 만든 예시 값이며, 실제로 잰 값이 아니다. 앱의 ⑤ 그래프는 가로축 시간, 세로축 이산화 탄소 농도로 그린다. 앱 그래프는 이산화 탄소만 받으므로, 산소 농도는 공책 모눈에 가로축(시간)을 앱 그래프와 똑같이 맞추고 세로축을 20.80~21.00 % 로 좁게 잡아 따로 그린다. 그다음 두 곡선이 오르는지 내려가는지 방향을 견주고, 27분 동안 늘어난 이산화 탄소 양을 27로 나누어 1분당 몇 ppm 씩 올랐는지 계산한다. (선택) 실제 기체 변화를 눈으로 보고 싶으면, 전날부터 어두운 곳에 둔 잎 봉지와 빈 봉지의 공기를 같은 부피씩 석회수에 통과시켜 두 시험관의 흐려진 정도를 견준다."
